package com.example.doctoolkit.ui;
import android.app.*; import android.content.*; import android.net.*; import android.os.*; import android.provider.MediaStore; import android.widget.*; import androidx.core.content.FileProvider; import com.example.doctoolkit.R; import java.io.*;
public class ResultActivity extends Activity{ private File file; public void onCreate(Bundle b){super.onCreate(b); setContentView(R.layout.activity_result); file=new File(getIntent().getStringExtra("path")); ((TextView)findViewById(R.id.previewText)).setText(preview(file)); findViewById(R.id.downloadButton).setOnClickListener(v->download()); findViewById(R.id.shareButton).setOnClickListener(v->share());} String preview(File f){try{byte[] b=java.nio.file.Files.readAllBytes(f.toPath()); String s=new String(b); return s.length()>4000?s.substring(0,4000):s;}catch(Exception e){return "Output ready: "+f.getName();}} void download(){try{ContentValues v=new ContentValues(); v.put(MediaStore.Downloads.DISPLAY_NAME,file.getName()); v.put(MediaStore.Downloads.IS_PENDING,1); Uri u=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v); try(OutputStream out=getContentResolver().openOutputStream(u); InputStream in=new FileInputStream(file)){byte[] b=new byte[8192]; for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);} v.clear(); v.put(MediaStore.Downloads.IS_PENDING,0); getContentResolver().update(u,v,null,null); Toast.makeText(this,"Downloaded",0).show();}catch(Exception e){Toast.makeText(this,e.getMessage(),1).show();}} void share(){Uri uri=FileProvider.getUriForFile(this,getPackageName()+".provider",file); Intent i=new Intent(Intent.ACTION_SEND).setType("application/octet-stream").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION); startActivity(Intent.createChooser(i,"Share output"));}}
